create or replace function public.recibir_compra(_compra_id uuid) returns jsonb language plpgsql security invoker set search_path='' as $$ declare c record; d record; v_rec numeric; v_total numeric:=0; begin select * into c from public.compras where id=_compra_id for update; if not found then raise exception 'Compra no encontrada'; end if; if not public.es_admin(auth.uid()) or not public.ve_sede(auth.uid(),c.sede_id) then raise exception 'No tienes permisos para recibir esta compra'; end if; if c.estado='cancelada' then raise exception 'No se puede recibir una compra cancelada'; end if; for d in select * from public.compra_detalles where compra_id=_compra_id for update loop v_rec:=d.cantidad-d.cantidad_recibida; if v_rec>0 then insert into public.inventario_movimientos(material_id,usuario_id,tipo,cantidad,motivo,referencia_externa,costo_unitario) values(d.material_id,auth.uid(),'entrada',v_rec,'Recepción de compra',c.numero,d.costo_unitario); update public.compra_detalles set cantidad_recibida=d.cantidad,updated_at=now() where id=d.id; v_total:=v_total+v_rec; end if; end loop; update public.compras set estado='recibida',updated_at=now() where id=_compra_id; return jsonb_build_object('compra_id',_compra_id,'cantidad_recibida',v_total); end; $$; revoke execute on function public.recibir_compra(uuid) from public,anon; grant execute on function public.recibir_compra(uuid) to authenticated;